"""Join the weelog_rg modules and weechat/weelog.py into one file for weechat.org.

    python3 scripts/build-weechat-script.py [OUT]   (default: dist/weelog.py)
"""
from __future__ import annotations

import ast
import sys
from dataclasses import dataclass, field
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
MODULES = ("parse", "index", "query", "search")
SCRIPT = REPO / "weechat" / "weelog.py"
GENERATED_NOTE = (
    "# Generated by scripts/build-weechat-script.py from weechat/weelog.py and the\n"
    "# weelog_rg package in the upstream repository. Edit those, not this file.\n"
)


@dataclass
class Segment:
    text: str
    defines: set[str] = field(default_factory=set)


def _is_package_import(node: ast.stmt) -> bool:
    return isinstance(node, ast.ImportFrom) and (
        node.level > 0 or (node.module or "").split(".")[0] == "weelog_rg"
    )


def _is_import_core(node: ast.stmt) -> bool:
    if isinstance(node, ast.FunctionDef):
        return node.name == "_import_core"
    return (isinstance(node, ast.Expr) and isinstance(node.value, ast.Call)
            and isinstance(node.value.func, ast.Name) and node.value.func.id == "_import_core")


def _defined(node: ast.stmt) -> set[str]:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        return {node.name}
    if isinstance(node, ast.Assign):
        return {t.id for t in node.targets if isinstance(t, ast.Name)}
    if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
        return {node.target.id}
    return set()


def split(src: str, imports: dict[str, set[str]], plain: set[str]) -> list[Segment]:
    tree = ast.parse(src)
    lines = src.splitlines()
    out: list[Segment] = []
    for i, node in enumerate(tree.body):
        if isinstance(node, ast.ImportFrom):
            if node.module == "__future__" or _is_package_import(node):
                continue
            if node.module == "weechat":
                raise SystemExit("unexpected 'from weechat import'")
            imports.setdefault(node.module or "", set()).update(a.name for a in node.names)
            continue
        if isinstance(node, ast.Import):
            plain.update(a.name for a in node.names)
            continue
        if i == 0 and isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) \
                and isinstance(node.value.value, str):
            continue
        if _is_import_core(node):
            continue
        start = node.lineno
        for d in getattr(node, "decorator_list", []):
            start = min(start, d.lineno)
        j = start - 1
        while j - 1 >= 0 and lines[j - 1].startswith("#"):
            j -= 1
        out.append(Segment("\n".join(lines[j:node.end_lineno]), _defined(node)))
    return out


def _references(node: ast.AST, known: set[str]) -> set[str]:
    # Callbacks are handed to WeeChat by name, so string constants count too.
    refs: set[str] = set()
    for n in ast.walk(node):
        if isinstance(n, ast.Name):
            refs.add(n.id)
        elif isinstance(n, ast.Global):
            refs.update(n.names)
        elif isinstance(n, ast.Constant) and isinstance(n.value, str) and n.value in known:
            refs.add(n.value)
    return refs


def prune(segments: list[Segment]) -> list[Segment]:
    """Keep plain statements and every definition reachable from them."""
    tree = ast.parse("\n\n\n".join(s.text for s in segments))
    assert len(tree.body) == len(segments)
    known = set().union(*(s.defines for s in segments))
    refs = [_references(node, known) - seg.defines for node, seg in zip(tree.body, segments, strict=True)]
    live = {i for i, s in enumerate(segments) if not s.defines}
    changed = True
    while changed:
        changed = False
        wanted = set().union(*(refs[i] for i in live))
        for i, s in enumerate(segments):
            if i not in live and s.defines & wanted:
                live.add(i)
                changed = True
    return [s for i, s in enumerate(segments) if i in live]


def imports_block(segments: list[Segment], imports: dict[str, set[str]], plain: set[str]) -> str:
    tree = ast.parse("\n\n\n".join(s.text for s in segments))
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    lines = [f"import {m}" for m in sorted(plain) if m != "weechat" and m.split(".")[0] in names]
    for mod in sorted(imports):
        used = sorted(n for n in imports[mod] if n in names)
        if not used:
            continue
        line = f"from {mod} import {', '.join(used)}"
        if len(line) > 88:
            line = f"from {mod} import (\n    " + ",\n    ".join(used) + ",\n)"
        lines.append(line)
    return "\n".join(lines) + "\n\nimport weechat\n"


def header(src: str) -> str:
    out = []
    for line in src.splitlines():
        if not line.startswith("#") or line.startswith("# Source form:"):
            break
        out.append(line)
    while out and out[-1] == "#":
        out.pop()
    return "\n".join(out) + "\n#\n" + GENERATED_NOTE


def build() -> str:
    imports: dict[str, set[str]] = {}
    plain: set[str] = set()
    segments: list[Segment] = []
    for name in MODULES:
        segments += split((REPO / "weelog_rg" / f"{name}.py").read_text(encoding="utf-8"),
                          imports, plain)
    script_src = SCRIPT.read_text(encoding="utf-8")
    segments += split(script_src, imports, plain)
    segments = prune(segments)
    out = (header(script_src) + "\nfrom __future__ import annotations\n\n"
           + imports_block(segments, imports, plain) + "\n\n"
           + "\n\n\n".join(s.text for s in segments) + "\n")
    compile(out, "weelog.py", "exec")
    for bad in ("import weelog_rg", "from weelog_rg", "from .", "_import_core"):
        if bad in out:
            raise SystemExit(f"build left package glue behind: {bad!r}")
    return out


def main(argv: list[str]) -> int:
    out_path = Path(argv[1]) if len(argv) > 1 else REPO / "dist" / "weelog.py"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(build(), encoding="utf-8")
    print(f"wrote {out_path} ({out_path.stat().st_size} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
